// A fake "database" that counts round trips — each query costs ~2 ms of network latency.
const db = {
  roundTrips: 0,
  customers: [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }, { id: 3, name: 'Chen' }],
  orders: [{ id: 101, customerId: 1 }, { id: 102, customerId: 1 }, { id: 103, customerId: 2 }],
  query(text, values = []) {
    this.roundTrips++;
    if (text.startsWith('SELECT * FROM customers')) return this.customers;
    if (text.includes('customer_id = $1')) return this.orders.filter((o) => o.customerId === values[0]);
    if (text.includes('customer_id = ANY($1)')) return this.orders.filter((o) => values[0].includes(o.customerId));
    throw new Error('unknown query');
  },
};

// N+1: one query for the list, then one query PER row (what lazy-loading ORMs do in a loop)
db.roundTrips = 0;
for (const c of db.query('SELECT * FROM customers')) {
  c.orders = db.query('SELECT * FROM orders WHERE customer_id = $1', [c.id]);
}
console.log('N+1 round trips:', db.roundTrips); // 4  (1 list query + 3 per-row queries)

// Batched: 2 queries total, no matter how many customers (ORM "eager loading" / DataLoader)
db.roundTrips = 0;
const customers = db.query('SELECT * FROM customers');
const orders = db.query('SELECT * FROM orders WHERE customer_id = ANY($1)', [customers.map((c) => c.id)]);
const byCustomer = Map.groupBy(orders, (o) => o.customerId); // Node 21+
for (const c of customers) c.orders = byCustomer.get(c.id) ?? [];
console.log('Batched round trips:', db.roundTrips); // 2
console.log(customers.map((c) => `${c.name}:${c.orders.length}`).join(' ')); // Alice:2 Bob:1 Chen:0

// SQL injection: concatenation lets input rewrite the statement
const email = "x' OR '1'='1";
const unsafe = `SELECT * FROM users WHERE email = '${email}'`;
console.log(unsafe); // SELECT * FROM users WHERE email = 'x' OR '1'='1'  <- matches every row
// Parameterized: the SQL text is fixed; the value travels separately and is never parsed as SQL
const safe = { text: 'SELECT * FROM users WHERE email = $1', values: [email] };
console.log(JSON.stringify(safe));
// {"text":"SELECT * FROM users WHERE email = $1","values":["x' OR '1'='1"]}
// With node-postgres: await pool.query(safe) — the server compares email to that literal string.
